// n8n - Code Node (JavaScript)

// Pega o primeiro item de entrada
const item = $input.first().json;
const key = item.body?.data?.key || {};

// Coleta os possíveis JIDs
const options = [key.remoteJid, key.remoteJidAlt].filter(Boolean);

// Função auxiliar: valida se o JID é de grupo válido
const isValidGroupJid = jid => {
  // JID de grupo válido tem apenas números e termina em @g.us
  return typeof jid === 'string' && /^\d{5,}@g\.us$/.test(jid);
};

// Verifica se algum é grupo
const groupJid = options.find(isValidGroupJid);

if (groupJid) {
  return [
    {
      json: {
        phone: 'grupo',
      },
    }
  ];
}

// Filtra JIDs válidos (não grupo, não @lid)
const validOptions = options.filter(jid =>
  typeof jid === 'string' &&
  !jid.includes('@lid') &&
  /^\d{5,}@s\.whatsapp\.net$/.test(jid)
);

const clean = validOptions[0] || '';

// Remove o sufixo do JID e retorna só o número
const phone = clean.replace(/@.*$/, '');

return [
  {
    json: {
      phone,
    },
  }
];

const min = 1000;
const max = 1800;

const numeroAleatorio = Math.floor(Math.random() * (max - min + 1)) + min;

return { numero_gerado: numeroAleatorio };

